// The one-command bootstrap of a nested hz (operator, 2026-10-01: "spin it up
// with a command that is generated by the red line project in the office").
//
//	POST /api/v1/nested/bootstrap          admin          {project, machine, rung, from, posture?, platform?, url?}
//	GET  /admin/hz-child/install/<grant>   public vhost   the script
//	POST /admin/hz-child/enrol/<grant>     public vhost   {public_key, platform, hostname?}
//	GET  /api/v1/nested/bin/<os>-<arch>    instance token or admin, over the upstream VPN
//
// DECLARE, THEN ENROL (CLAUDE.md #7). Generate is an admin act that declares
// the machine (with its hz marker, owned by the project) and the rung (placed
// in it) before any box exists. The box can only redeem what was declared: the
// grant names the machine, and enrolment refuses if the declaration has gone.
//
// THE CHILD DIALS (#1). Every request here is made BY the box: the script, the
// enrolment, the binary. Nothing here contacts it.
//
// NO PRIVATE KEY CROSSES (#4). The box generates its WireGuard keypair and
// sends the public half; the parent stores a wg0 peer (public key, address)
// and nothing else. The instance token is minted here and shown once, in the
// enrolment answer; the parent keeps its sha256 (MachineHZ.TokenSHA256). The
// child's LOCAL service token is generated on the box and never sent up.

// childUpstreamIface is the child's WireGuard interface name — its config is
// /etc/wireguard/<this>.conf. Not wg0: a child that later runs its own human
// VPN keeps wg0 for that.
const childUpstreamIface = config.ChildUpstreamIface

// childTokenFile is where the child keeps the instance token (0600).
const childTokenFile = "/etc/homelab-horizon/upstream.token"

// childAdminUser is the account the bootstrap creates on a child that has
// none, and childAdminTokenFile where its personal API token goes (0600,
// written by `homelab-horizon user create`). Without an account a child can
// be synced by nobody, and its first-account sign-up (bootstrapAllowed) stays
// open to anyone who reaches its API.
const (
	childAdminUser      = "hz-local-admin"
	childAdminTokenFile = "/etc/homelab-horizon/admin.token"
)

// childListenPort is the port a seeded child's hz answers on: the default
// listen address (config.Default, ":8080"), which the seed does not change.
const childListenPort = "8080"

// bootstrapNameRe is the shape a machine or rung name must have to be
// bootstrapped: it becomes a VPN client name, a service name and a query
// parameter, so it stays a plain token.
var bootstrapNameRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$`)

// upstreamClientName is the VPN client a nested machine gets, matching the
// UI's declare flow (ui/src/components/instances/declareNested.ts).
func upstreamClientName(machine string) string { return machine + "-upstream" }

// childServiceName is the local service the child declares for its rung, so
// the app on the box authenticates to the CHILD with a service token (N4a).
func childServiceName(project, rung string) string { return project + "-" + rung }

// pendingHZURL is the marker URL of a machine declared before its box exists:
// .invalid is reserved (RFC 2606), so it can never resolve to anything — it
// says "not known yet" rather than guessing. Enrolment replaces it.
func pendingHZURL(machine string) string {
	return "http://" + strings.ToLower(machine) + ".pending.invalid"
}

func isPendingHZURL(raw string) bool {
	u, err := url.Parse(raw)
	return err == nil && strings.HasSuffix(u.Hostname(), ".pending.invalid")
}

// applyWGChange reloads wg0 and rebuilds the WG chains after a peer edit.
func (s *Server) applyWGChange() {
	if s.wgReload != nil {
		if err := s.wgReload(); err != nil {
			slog.Warn("wg reload", "err", err)
		}
		return
	}
	if err := s.wg.Reload(); err != nil {
		slog.Warn("wg.Reload", "err", err)
	}
	s.rebuildWGChains()
}

// childInstallBase is the public-vhost origin the command points at. Refused
// without kiosk_url: the command is run on a box outside the network, and the
// admin hostname 404s the install routes (requirePublicVhost) — building the
// command from the admin origin would print a command that cannot work.
func (s *Server) childInstallBase() (string, error) {
	raw := strings.TrimSpace(s.cfg().KioskURL)
	if raw == "" {
		return "", errors.New("this hz has no public vhost (kiosk_url is not set), so there is no address a fresh box outside the network can fetch the bootstrap from — set kiosk_url in Settings first")
	}
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" || (u.Scheme != "https" && u.Scheme != "http") {
		return "", fmt.Errorf("kiosk_url %q is not an http(s) URL with a host, so the bootstrap command would point nowhere — fix it in Settings", raw)
	}
	return u.Scheme + "://" + u.Host, nil
}

// bootstrapPlan is the pure half of generate: the config with the machine and
// the rung declared (or reused), and what was reused.
func bootstrapPlan(cfg *config.Config, req apitypes.NestedBootstrapReq) (*config.Config, []string, error) {
	next := *cfg
	reused := []string{}
	project, machine, rung := req.Project, req.Machine, req.Rung

	if !bootstrapNameRe.MatchString(machine) {
		return nil, nil, fmt.Errorf("machine name %q must be letters, digits, '.', '_' or '-' (it becomes a VPN client and a log label)", machine)
	}
	if !bootstrapNameRe.MatchString(rung) {
		return nil, nil, fmt.Errorf("rung name %q must be letters, digits, '.', '_' or '-' (it becomes the child's service name)", rung)
	}
	if !projectDeclared(cfg, project) {
		return nil, nil, fmt.Errorf("no project %q — declare the project first, then generate the command from its page", project)
	}

	if m, ok := cfg.FindMachine(machine); ok {
		if m.HZ == nil {
			return nil, nil, fmt.Errorf("machine %q is already declared and runs no hz — it is some other box. Pick another name, or remove %s first", machine, machine)
		}
		if m.Project != project {
			owner := m.Project
			if owner == "" {
				owner = "global"
			}
			return nil, nil, fmt.Errorf("machine %q is already declared, owned by %s, not %s — generate the command from that project, or change its owner first", machine, owner, project)
		}
		reused = append(reused, "machine")
	} else {
		u := strings.TrimSpace(req.URL)
		if u == "" {
			u = pendingHZURL(machine)
		}
		if err := next.AddMachine(config.Machine{Name: machine, Project: project, HZ: &config.MachineHZ{URL: u}}); err != nil {
			return nil, nil, err
		}
	}

	if e, err := cfg.LookupEnvironment(project, rung); err == nil {
		switch {
		case e.Upstream != machine && e.Upstream == "":
			return nil, nil, fmt.Errorf("rung %s/%s already exists and is placed HERE, not in %s — a bootstrap does not move a rung. Pick another rung name, or set its upstream to %s first", project, rung, machine, machine)
		case e.Upstream != machine:
			return nil, nil, fmt.Errorf("rung %s/%s already exists and is placed in %s, not %s — one rung has one upstream", project, rung, e.Upstream, machine)
		case e.From != req.From:
			return nil, nil, fmt.Errorf("rung %s/%s already exists and promotes from %q, not %q — say the one it has, or change it first", project, rung, e.From, req.From)
		case req.Posture != "" && e.Posture != req.Posture:
			return nil, nil, fmt.Errorf("rung %s/%s already exists at posture %s, not %s — leave posture out to reuse it, or change it first", project, rung, e.Posture, req.Posture)
		}
		reused = append(reused, "rung")
	} else {
		if _, err := cfg.LookupEnvironment(project, req.From); err != nil {
			return nil, nil, fmt.Errorf("from-rung %q is not a rung of %s — the new rung is promoted into from an existing one", req.From, project)
		}
		posture := req.Posture
		if posture == "" {
			posture = "prod"
		}
		if err := next.AddEnvironment(config.Environment{Project: project, Name: rung, Posture: posture, From: req.From, Upstream: machine}); err != nil {
			return nil, nil, err
		}
	}

	// The VPN client the box will be: refused now if its name is taken by
	// anything but this machine's own upstream client, so the command never
	// fails at enrolment over something knowable here.
	client := upstreamClientName(machine)
	if m, ok := cfg.FindMachine(machine); ok && m.HZ != nil && m.HZ.VPNClient != "" {
		client = m.HZ.VPNClient
	}
	for _, p := range cfg.WGPeers {
		if p.Name != client {
			continue
		}
		if prof := cfg.GetPeerProfile(client); prof != config.ProfileUpstream {
			return nil, nil, fmt.Errorf("a VPN client named %s already exists with profile %q — the box's client must be %q. Rename or remove that client first", client, prof, config.ProfileUpstream)
		}
		if owner := cfg.UpstreamLinkOf(client); owner != "" && owner != machine {
			return nil, nil, fmt.Errorf("VPN client %s is the link of nested hz %s, not %s", client, owner, machine)
		}
	}
	return &next, reused, nil
}

func projectDeclared(cfg *config.Config, name string) bool {
	for _, p := range cfg.Projects {
		if p.Name == name {
			return true
		}
	}
	return false
}

// POST /api/v1/nested/bootstrap
func (s *Server) handleAPINestedBootstrap(w http.ResponseWriter, r *http.Request) {
	if !s.isAdmin(r) {
		writeJSONError(w, http.StatusUnauthorized, "Unauthorized")
		return
	}
	if r.Method != http.MethodPost {
		writeJSONError(w, http.StatusMethodNotAllowed, "POST required")
		return
	}
	var req apitypes.NestedBootstrapReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSONError(w, http.StatusBadRequest, "Invalid JSON: "+err.Error())
		return
	}
	req.Project, req.Machine, req.Rung = strings.TrimSpace(req.Project), strings.TrimSpace(req.Machine), strings.TrimSpace(req.Rung)
	req.From, req.Posture, req.Platform = strings.TrimSpace(req.From), strings.TrimSpace(req.Posture), strings.TrimSpace(req.Platform)
	for _, f := range []struct{ v, msg string }{
		{req.Project, "project is required — the nested hz is declared in, and owned by, a project"},
		{req.Machine, "machine is required — the name the nested hz's box is declared under"},
		{req.Rung, "rung is required — the rung the nested hz serves, declared as <project>/<rung>"},
		{req.From, "from is required — the existing rung that promotes into the new one (e.g. staging)"},
	} {
		if f.v == "" {
			writeJSONError(w, http.StatusBadRequest, f.msg)
			return
		}
	}
	if req.Platform != "" && !childPlatformRe.MatchString(req.Platform) {
		writeJSONError(w, http.StatusBadRequest, "platform "+strconv.Quote(req.Platform)+" is not one a nested hz is bootstrapped on: "+strings.Join(ChildPlatforms, " or "))
		return
	}

	base, err := s.childInstallBase()
	if err != nil {
		writeJSONError(w, http.StatusConflict, err.Error())
		return
	}
	if msg := s.upstreamReadiness(); msg != "" {
		writeJSONError(w, http.StatusConflict, msg)
		return
	}
	have, missing := s.childBins.Available()
	if req.Platform != "" {
		if _, err := s.childBins.Get(req.Platform); err != nil {
			writeJSONError(w, http.StatusConflict, "no command generated: "+err.Error())
			return
		}
	} else if len(have) == 0 {
		writeJSONError(w, http.StatusConflict, "no command generated: no server binary for a child is uploaded ("+strings.Join(missing, ", ")+
			" missing) — run `make child-bins-upload HOST=<this hz>` (or bin/deploy) from the hz repo first")
		return
	}

	next, reused, err := bootstrapPlan(s.cfg(), req)
	if err != nil {
		writeJSONError(w, http.StatusBadRequest, err.Error())
		return
	}
	// Machine and rung are ONE save, and the grant is minted only after it
	// lands: a refused save leaves nothing declared and no command.
	if err := s.updateConfig(func(c *config.Config) { *c = *next }); err != nil {
		writeJSONError(w, http.StatusInternalServerError, "failed to save: "+err.Error())
		return
	}
	gr, revoked, err := s.childGrantStore().issue(req.Machine, req.Project, req.Rung)
	if err != nil {
		writeJSONError(w, http.StatusInternalServerError, err.Error())
		return
	}
	resp := apitypes.NestedBootstrapResp{
		Command:   "curl -fsSL " + base + "/admin/hz-child/install/" + gr.Token + " | sudo bash",
		ExpiresAt: gr.Expires.Unix(),
		Machine:   req.Machine, Project: req.Project, Rung: req.Project + "/" + req.Rung,
		Platforms: nonNil(have), Missing: nonNil(missing), Reused: reused, Revoked: revoked,
	}
	if req.Platform == "" && len(missing) > 0 {
		resp.Warning = "This command works only on " + strings.Join(have, " or ") + " boxes: no server binary is uploaded for " +
			strings.Join(missing, ", ") + ". On such a box the script stops before it changes anything."
	}
	slog.Info("nested bootstrap command generated", "machine", req.Machine, "rung", resp.Rung, "by", s.adminActor(r), "revoked_previous", revoked)
	writeJSON(w, resp)
}

func nonNil(in []string) []string {
	if in == nil {
		return []string{}
	}
	return in
}

// upstreamReadiness is "" when a child could reach this hz over an upstream
// VPN client, or the sentence saying why not.
func (s *Server) upstreamReadiness() string {
	if s.wg == nil {
		return "WireGuard is not configured on this hz, so there is no VPN a nested hz could reach it through"
	}
	cfg := s.cfg()
	if strings.TrimSpace(cfg.ServerPublicKey) == "" || strings.TrimSpace(cfg.ServerEndpoint) == "" {
		return "this hz's WireGuard public key or endpoint is not set (server_public_key / server_endpoint), so a box could not be told where to connect"
	}
	if _, err := s.upstreamParentURL(); err != nil {
		return "a nested hz could not reach this hz over the VPN: " + err.Error()
	}
	return ""
}

// GET /admin/hz-child/install/<grant> — the script, for a live grant.
//
// An unknown, used or expired grant gets a SCRIPT that says so and exits 1,
// served 200: the command pipes into bash, and a 404 under curl -f reaches
// bash as empty input, which "succeeds" silently. The refusal names nothing
// but the fact — no machine, no project.
func (s *Server) handleChildInstallScript(w http.ResponseWriter, r *http.Request) {
	if !s.requirePublicVhost(w, r) {
		return
	}
	w.Header().Set("Content-Type", "text/x-shellscript; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	token := strings.TrimPrefix(r.URL.Path, "/admin/hz-child/install/")
	gr, ok := s.childGrantStore().peek(token)
	if !ok {
		_, _ = w.Write([]byte(childRefusalScript))
		return
	}
	have, _ := s.childBins.Available()
	parentAddr := ""
	if u, err := s.upstreamParentURL(); err == nil {
		if pu, perr := url.Parse(u); perr == nil {
			parentAddr = pu.Hostname()
		}
	}
	_, _ = w.Write([]byte(renderChildInstallScript(s.installBaseURL(r), gr, have, parentAddr)))
}

// renderChildInstallScript fills the template. Every value is a token, a URL
// hz built, a validated name or a constant — none is free text.
//
// parentAddr is the parent's VPN address. The script refuses, BEFORE it
// enrols, a box where that address is already assigned to a local interface:
// the first real run (2026-10-01) hit a leftover wg0 holding the parent's own
// range, so the parent address was local and nothing entered the tunnel.
func renderChildInstallScript(base string, gr childGrant, platforms []string, parentAddr string) string {
	rep := strings.NewReplacer(
		"@@HZ_BASE@@", strings.TrimSuffix(base, "/"),
		"@@GRANT@@", gr.Token,
		"@@MACHINE@@", gr.Machine,
		"@@PROJECT@@", gr.Project,
		"@@RUNG@@", gr.Rung,
		"@@PLATFORMS@@", strings.Join(platforms, " "),
		"@@EXPIRES@@", gr.Expires.UTC().Format(time.RFC3339),
		"@@IFACE@@", childUpstreamIface,
		"@@TOKEN_FILE@@", childTokenFile,
		"@@ADMIN_USER@@", childAdminUser,
		"@@ADMIN_TOKEN_FILE@@", childAdminTokenFile,
		"@@PARENT_ADDR@@", parentAddr,
	)
	return rep.Replace(hzChildInstallScript)
}

// POST /admin/hz-child/enrol/<grant>
func (s *Server) handleChildEnrol(w http.ResponseWriter, r *http.Request) {
	if !s.requirePublicVhost(w, r) {
		return
	}
	if r.Method != http.MethodPost {
		writeJSONError(w, http.StatusMethodNotAllowed, "POST required")
		return
	}
	token := strings.TrimPrefix(r.URL.Path, "/admin/hz-child/enrol/")
	var req apitypes.NestedEnrolReq
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 4096)).Decode(&req); err != nil {
		writeJSONError(w, http.StatusBadRequest, "Invalid JSON: "+err.Error())
		return
	}
	// Everything checkable is checked BEFORE the grant is consumed, so a bad
	// request costs the operator nothing: the same command still works.
	req.PublicKey = strings.TrimSpace(req.PublicKey)
	if !wireguard.ValidatePublicKey(req.PublicKey) {
		writeJSONError(w, http.StatusBadRequest, "public_key is not a WireGuard public key (44 characters of base64) — send the output of `wg pubkey`, never the private key")
		return
	}
	if _, ok := s.childGrantStore().peek(token); !ok {
		writeJSONError(w, http.StatusGone, "this bootstrap command was already used, has expired or was replaced by a newer one — generate a new command on the parent hz")
		return
	}
	bin, err := s.childBins.Get(req.Platform)
	if err != nil {
		writeJSONError(w, http.StatusConflict, err.Error()+" — nothing was changed; upload it and re-run the same command")
		return
	}
	if msg := s.upstreamReadiness(); msg != "" {
		writeJSONError(w, http.StatusConflict, msg+" — nothing was changed")
		return
	}
	for _, p := range s.wg.GetPeers() {
		if p.PublicKey == req.PublicKey {
			writeJSONError(w, http.StatusConflict, "that public key is already a VPN client of this hz ("+p.Name+") — the box must generate a fresh key")
			return
		}
	}

	s.childEnrolMu.Lock()
	defer s.childEnrolMu.Unlock()
	gr, ok := s.childGrantStore().take(token)
	if !ok {
		writeJSONError(w, http.StatusGone, "this bootstrap command was already used, has expired or was replaced by a newer one — generate a new command on the parent hz")
		return
	}
	resp, status, err := s.enrolChild(gr, req, bin)
	if err != nil {
		writeJSONError(w, status, err.Error()+" — the command is used up; generate a new one on the parent hz")
		return
	}
	s.childGrantStore().markEnrolled(gr.Machine)
	slog.Info("nested hz enrolled", "machine", gr.Machine, "rung", resp.Rung, "vpn_address", resp.WG.Address, "hostname", req.Hostname)
	writeJSON(w, resp)
}

// enrolChild does the work of one enrolment, with the grant already consumed.
// The wg0 edit is rolled back if the config save is refused.
func (s *Server) enrolChild(gr childGrant, req apitypes.NestedEnrolReq, bin childBin) (apitypes.NestedEnrolResp, int, error) {
	cfg := s.cfg()
	m, ok := cfg.FindMachine(gr.Machine)
	if !ok || m.HZ == nil {
		return apitypes.NestedEnrolResp{}, http.StatusConflict, fmt.Errorf("machine %s is no longer declared as a nested hz on the parent", gr.Machine)
	}
	env, err := cfg.LookupEnvironment(gr.Project, gr.Rung)
	if err != nil || env.Upstream != gr.Machine {
		return apitypes.NestedEnrolResp{}, http.StatusConflict, fmt.Errorf("rung %s/%s is no longer placed in %s on the parent", gr.Project, gr.Rung, gr.Machine)
	}
	parentURL, err := s.upstreamParentURL()
	if err != nil {
		return apitypes.NestedEnrolResp{}, http.StatusConflict, err
	}

	client := upstreamClientName(m.Name)
	if m.HZ.VPNClient != "" {
		client = m.HZ.VPNClient
	}
	var existing *wireguard.Peer
	for _, p := range s.wg.GetPeers() {
		if p.Name == client {
			p := p
			existing = &p
		}
	}
	var address string
	var rollback func()
	if existing != nil {
		// Re-provisioning: the box's new key replaces the old one, which
		// stops authenticating at the next wg reload.
		if err := s.wg.ReplacePeerKey(existing.PublicKey, req.PublicKey); err != nil {
			return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
		}
		old := existing.PublicKey
		rollback = func() { _ = s.wg.ReplacePeerKey(req.PublicKey, old) }
		address = primaryPeerIP(existing.AllowedIPs)
	} else {
		ip, err := s.wg.GetNextIP(cfg.VPNRange)
		if err != nil {
			return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
		}
		if err := s.wg.AddPeer(client, req.PublicKey, ip); err != nil {
			return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
		}
		rollback = func() { _ = s.wg.RemovePeer(req.PublicKey) }
		address = primaryPeerIP(ip)
	}

	tok, err := newInstanceToken()
	if err != nil {
		rollback()
		return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
	}
	next := *cfg
	profiles := make(map[string]string, len(cfg.VPNProfiles)+1)
	for k, v := range cfg.VPNProfiles {
		profiles[k] = v
	}
	next.VPNProfiles = profiles
	next.SetPeerProfile(client, config.ProfileUpstream)
	next.SetPeerProject(client, m.Project)
	next.WGPeers = s.snapshotWGPeers()
	hz := config.MachineHZ{URL: m.HZ.URL, VPNClient: client}
	if isPendingHZURL(hz.URL) {
		hz.URL = "http://" + net.JoinHostPort(address, childListenPort)
	}
	if _, err := next.SetMachine(m.Name, config.MachinePatch{HZ: &hz}); err != nil {
		rollback()
		return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
	}
	if err := next.SetInstanceTokenHash(m.Name, tokenDigest(tok)); err != nil {
		rollback()
		return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, err
	}
	if err := s.updateConfig(func(c *config.Config) { *c = next }); err != nil {
		rollback()
		return apitypes.NestedEnrolResp{}, http.StatusInternalServerError, fmt.Errorf("failed to save: %w", err)
	}
	s.applyWGChange()

	service := childServiceName(gr.Project, gr.Rung)
	return apitypes.NestedEnrolResp{
		WG: apitypes.NestedEnrolWG{
			Address:       address,
			PeerPublicKey: cfg.ServerPublicKey,
			Endpoint:      cfg.ServerEndpoint,
			AllowedIPs:    s.gatewayWGIP() + "/32",
		},
		ParentURL:     parentURL,
		InstanceToken: tok,
		Machine:       m.Name,
		Project:       gr.Project,
		Rung:          gr.Rung,
		ServiceName:   service,
		Binary: apitypes.NestedEnrolBinary{
			URL:     parentURL + "/api/v1/nested/bin/" + bin.Platform,
			SHA256:  bin.SHA256,
			Version: bin.Version,
		},
		Seed: childSeed(gr.Project, gr.Rung, env.Posture, service, parentURL),
	}, 0, nil
}

// childSeed is the child's config.json seed. The service token is EMPTY: the
// box generates it, and the parent never learns it.
func childSeed(project, rung, posture, service, parentURL string) apitypes.NestedChildSeed {
	return apitypes.NestedChildSeed{
		Projects:     []apitypes.NestedSeedProject{{Name: project}},
		Environments: []apitypes.NestedSeedEnvironment{{Project: project, Name: rung, Posture: posture}},
		Services:     []apitypes.NestedSeedService{{Name: service, Project: project, Environment: rung, Domains: []string{}}},
		Upstream: apitypes.NestedSeedUpstream{
			URL:       parentURL,
			TokenFile: childTokenFile,
			Rungs:     []apitypes.NestedSeedRung{{Project: project, Environment: rung}},
		},
	}
}

// primaryPeerIP is the /32 address of a peer's AllowedIPs, without the mask.
func primaryPeerIP(allowed string) string {
	for _, part := range strings.Split(allowed, ",") {
		part = strings.TrimSpace(part)
		if strings.HasSuffix(part, "/32") {
			return strings.TrimSuffix(part, "/32")
		}
	}
	return strings.TrimSpace(strings.Split(strings.TrimSpace(allowed), "/")[0])
}

// GET /api/v1/nested/bin/<os>-<arch> — the server binary a child installs,
// fetched OVER the upstream VPN with the instance token the enrolment handed
// it (or by an admin). Not on the public vhost: the 30MB server binary is no
// more a free download than the client binaries are.
func (s *Server) handleNestedBinary(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		writeJSONError(w, http.StatusMethodNotAllowed, "GET required")
		return
	}
	if _, ok := s.instanceCaller(r); !ok && !s.isAdmin(r) {
		writeJSONError(w, http.StatusUnauthorized, "Unauthorized — this download needs the instance token a nested hz was enrolled with")
		return
	}
	bin, err := s.childBins.Get(strings.TrimPrefix(r.URL.Path, "/api/v1/nested/bin/"))
	if err != nil {
		writeJSONError(w, http.StatusNotFound, err.Error())
		return
	}
	f, err := os.Open(bin.Path)
	if err != nil {
		writeJSONError(w, http.StatusInternalServerError, err.Error())
		return
	}
	defer func() { _ = f.Close() }()
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", "attachment; filename=homelab-horizon")
	w.Header().Set("X-HZ-SHA256", bin.SHA256)
	w.Header().Set("X-HZ-Version", bin.Version)
	http.ServeContent(w, r, "homelab-horizon", time.Time{}, f)
}
